"""Launch and validate exactly one fresh natural-GC diagnostic JVM; never retry."""

import argparse
import hashlib
import json
from pathlib import Path
import re
import subprocess
import sys


DIAGNOSTICS = Path(__file__).resolve().parent
PHASE = DIAGNOSTICS.parent
ROOT = PHASE.parents[1]
MAIN = "org.eclipse.rdf4j.sail.lmdb.evaluation.NativeDirectMemoNaturalGcDiagnostic"
KEYS = 8
ROUNDS = 17
REQUESTS = KEYS * ROUNDS
PRESSURE_BYTES = 16 * 32 * 1024 * 1024
EXPLICIT_GC = re.compile(r"System\.gc|Diagnostic Command|Heap (?:Inspection|Dump) Initiated GC", re.IGNORECASE)
MASK_FIELDS = (
    "previous_values_cleared_before_demand_mask", "previous_payloads_cleared_before_demand_mask",
    "original_values_cleared_before_demand_mask", "original_payloads_cleared_before_demand_mask",
    "previous_values_cleared_at_lookup_mask", "returned_cold_mask",
    "same_previous_identity_mask", "same_original_identity_mask",
)


def require(condition, message):
    if not condition:
        raise AssertionError(message)


def sha(path):
    with path.open("rb") as handle:
        return hashlib.file_digest(handle, "sha256").hexdigest()


def save(path, value):
    with path.open("x") as handle:
        json.dump(value, handle, indent=2, sort_keys=True)
        handle.write("\n")


def validate(attempt, arm, characters, consumer):
    process = json.loads((attempt / "process.json").read_text())
    require(process["exitCode"] == 0 and process["timedOut"] is False, "Diagnostic JVM did not finish normally")
    require(process["inputsUnchanged"] is True and process["comparisonSample"] is False,
            "Diagnostic provenance or input identity failed")
    for name, expected in process["rawHashes"].items():
        require(sha(attempt / name) == expected, "Raw hash mismatch: " + name)
    command = json.loads((attempt / "command.json").read_text())["argv"]
    require(command.count(MAIN) == 1 and command[-5:] == [
        MAIN, arm, str(characters), consumer, str(attempt / "store" / "values")
    ], "Unexpected diagnostic main, arguments, or values directory")
    require(all(flag in command for flag in ("-Xms128m", "-Xmx128m", "-XX:+UseG1GC")),
            "Diagnostic requires the fixed 128 MiB G1 heap")
    gc_log = (attempt / "gc.log").read_text()
    require("Using G1" in gc_log, "GC log does not identify G1")
    require(EXPLICIT_GC.search(gc_log) is None, "GC log records an explicit collection request")
    records = [json.loads(line) for line in (attempt / "stdout.jsonl").read_text().splitlines()
               if line.startswith("{")]
    require(len(records) == ROUNDS + 2, "Expected metadata, 17 rounds, and one summary")
    metadata, summary = records[0], records[-1]
    rounds = records[1:-1]
    require(metadata["kind"] == "natural-gc-metadata" and summary["kind"] == "natural-gc-summary",
            "Wrong record ordering or kind")
    require((metadata["arm"], metadata["characters_per_key"], metadata["consumer"]) == (arm, characters, consumer),
            "Metadata case differs from the requested case")
    require((summary["arm"], summary["characters"], summary["consumer"]) == (arm, characters, consumer),
            "Summary case differs from the requested case")
    require(metadata["values_directory"] == str(attempt / "store" / "values"), "Wrong values directory")
    require(metadata["heap_max_bytes"] == metadata["heap_initial_bytes"] == 128 << 20, "Heap identity mismatch")
    require(metadata["keys"] == KEYS and metadata["rounds_after_initial"] == 16, "Wrong key/round count")
    require(metadata["pressure_array_payload_bytes_per_round"] == 32 << 20
            and metadata["pressure_array_bytes"] == 256 << 10
            and metadata["pressure_arrays_per_round"] == 128, "Pressure schedule differs")
    require(metadata["source_cache_settings_changed"] is False and metadata["explicit_gc_requested"] is False,
            "Source-cache settings or explicit-GC scope differs")
    keys = metadata["keys_and_slots"]
    require(len(keys) == KEYS and len({key["id"] for key in keys}) == KEYS
            and len({key["slot"] for key in keys}) == KEYS
            and all(0 <= key["slot"] < 4096 for key in keys), "Keys are not distinct and collision-free")
    require(summary["requests"] == REQUESTS and summary["pressure_rounds"] == 16
            and summary["pressure_array_payload_bytes"] == PRESSURE_BYTES, "Summary request/pressure count differs")
    require(summary["ledger_after_close"] == summary["manager_after_close"] == 0
            and summary["source_closed"] is True, "Memo or source cleanup failed")
    expected_reservation = 0 if arm == "ordinary" else 147536 if arm == "strong" else 606448
    require(summary["peak_ledger_bytes"] == expected_reservation, "Unexpected metadata reservation peak")
    checksum = summary["checksum_hex"]
    require(re.fullmatch(r"[0-9a-f]{1,16}", checksum) is not None, "Malformed checksum")
    total_calls = total_cold = same_previous = cleared_values = cleared_payloads = canaries = 0
    previous_gc_count = previous_gc_millis = 0
    previous_original_values = previous_original_payloads = 0
    last_hits = 0
    for ordinal, row in enumerate(rounds):
        require(row["kind"] == "natural-gc-round" and row["round"] == ordinal, "Round missing, repeated, or reordered")
        require(row["checksum_hex"] == checksum, "Round checksum differs from the seed/summary oracle")
        require(0 <= row["source_calls"] <= KEYS
                and 0 <= row["cold_to_initialized_observations"] <= row["source_calls"], "Invalid round call/completion counts")
        for name in MASK_FIELDS:
            require(isinstance(row[name], int) and 0 <= row[name] < 256, "Invalid observation mask: " + name)
        cold = row["returned_cold_mask"].bit_count()
        require(cold == row["cold_to_initialized_observations"], "Cold mask/completion count differs")
        total_calls += row["source_calls"]
        total_cold += cold
        same_previous += row["same_previous_identity_mask"].bit_count()
        cleared_values += row["previous_values_cleared_before_demand_mask"].bit_count()
        cleared_payloads += row["previous_payloads_cleared_before_demand_mask"].bit_count()
        canaries += int(row["canary_cleared"])
        require(row["source_calls_cumulative"] == total_calls, "Cumulative source calls differ")
        expected_hits = 0 if arm == "ordinary" else (ordinal + 1) * KEYS - total_calls
        expected_probes = 0 if arm == "ordinary" else (ordinal + 1) * KEYS
        require(row["memo_hits_cumulative"] == expected_hits and row["memo_probes_cumulative"] == expected_probes,
                "Memo counters disagree with the logical request count")
        require(row["ledger_bytes"] == expected_reservation, "Unexpected live metadata reservation")
        require(row["same_previous_identity_mask"].bit_count() >= expected_hits - last_hits,
                "A memo hit did not preserve the prior representative")
        last_hits = expected_hits
        require(row["previous_values_cleared_before_demand_mask"] & ~row["previous_values_cleared_at_lookup_mask"] == 0,
                "A cleared weak observer became live again")
        require(row["same_previous_identity_mask"] & row["previous_values_cleared_at_lookup_mask"] == 0,
                "A cleared previous observer matched a returned identity")
        require(row["same_original_identity_mask"] & row["original_values_cleared_before_demand_mask"] == 0,
                "A cleared original observer matched a returned identity")
        require(previous_original_values & ~row["original_values_cleared_before_demand_mask"] == 0
                and previous_original_payloads & ~row["original_payloads_cleared_before_demand_mask"] == 0,
                "Original weak-observer clearing is not monotonic")
        previous_original_values = row["original_values_cleared_before_demand_mask"]
        previous_original_payloads = row["original_payloads_cleared_before_demand_mask"]
        require(row["gc_count_since_reopen"] >= previous_gc_count
                and row["gc_millis_since_reopen"] >= previous_gc_millis, "GC totals decreased")
        previous_gc_count, previous_gc_millis = row["gc_count_since_reopen"], row["gc_millis_since_reopen"]
        require(0 <= row["whole_jvm_heap_used_bytes"] <= 128 << 20, "Whole-heap observation outside its bound")
        if ordinal == 0:
            require(row["source_calls"] == row["cold_to_initialized_observations"] == KEYS
                    and row["returned_cold_mask"] == 255 and row["canary_cleared"] is False,
                    "Reopened store did not start with eight cold representatives")
        if consumer == "one":
            require((previous_original_values | previous_original_payloads) & 1 == 0,
                    "The intentional consumer's original Value or payload cleared")
            if ordinal and arm != "ordinary":
                require(row["same_original_identity_mask"] & 1 == 1, "Retained memo entry lost its identity")
    require(summary["source_calls"] == total_calls and summary["cold_to_initialized_observations"] == total_cold,
            "Round totals disagree with summary calls/completions")
    require(summary["source_returned_cold"] == total_cold
            and summary["source_returned_initialized"] + total_cold == total_calls,
            "Source initialization observations do not cover all calls")
    require(summary["same_previous_identity_returns"] == same_previous
            and 0 <= summary["same_previous_identity_from_source"] <= same_previous, "Identity-return totals differ")
    require(summary["previous_value_cleared_observations"] == cleared_values
            and summary["previous_payload_cleared_observations"] == cleared_payloads
            and summary["cleared_canaries"] == canaries, "Weak-observer totals disagree")
    require(summary["gc_count_delta"] >= previous_gc_count and summary["gc_millis_delta"] >= previous_gc_millis,
            "Final GC totals precede the last round")
    memo = summary["memo"]
    if arm == "ordinary":
        require(memo is None and total_calls == REQUESTS, "Ordinary arm unexpectedly reused the memo")
        require(summary["same_previous_identity_from_source"] == same_previous, "Ordinary identities bypassed the source")
    else:
        require(memo["probes"] == REQUESTS and memo["hits"] == REQUESTS - total_calls
                and memo["capacity_at_close"] == 4096 and memo["occupied_slots_at_close"] == KEYS
                and memo["reserved_after_close"] == 0 and memo["peak_reservation_bytes"] == expected_reservation,
                "Memo summary or cleanup differs")
        if arm == "strong":
            require(total_calls == KEYS and memo["collected_misses"] == 0
                    and memo["weak_entry_allocations"] == 0, "Strong control did not preserve its representatives")
        else:
            require(memo["collected_misses"] == total_calls - KEYS
                    and memo["weak_entry_allocations"] == total_calls,
                    "Collision-free weak misses do not reconcile to collected entries")
    return {
        "status": "pass", "arm": arm, "characters": characters, "consumer": consumer,
        "records": len(records), "round_records": len(rounds), "requests": REQUESTS,
        "pressure_array_payload_bytes": PRESSURE_BYTES, "explicit_gc_in_log": False,
        "source_calls": total_calls, "cold_to_initialized_observations": total_cold,
        "source_observations_are_physical_decode_counts": False,
        "same_previous_identity_returns": same_previous,
        "collected_misses": None if memo is None else memo["collected_misses"],
        "natural_gc_count_delta": summary["gc_count_delta"], "cleared_canaries": canaries,
        "checksum_hex": checksum, "query_and_manager_ledger_after_close": 0,
        "process_sha256": sha(attempt / "process.json"), "raw_hashes": process["rawHashes"],
        "input_manifest_sha256": sha(attempt / "inputs.json"),
        "weak_collection_count_was_not_prespecified": True,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--arm", choices=("ordinary", "strong", "weak"), required=True)
    parser.add_argument("--characters", type=int, choices=(1024, 1048577), required=True)
    parser.add_argument("--consumer", choices=("none", "one"), required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--classpath", type=Path, default=DIAGNOSTICS / "natural-runtime-v1" / "classpath.txt")
    parser.add_argument("--slot-granted", action="store_true")
    args = parser.parse_args()
    require(args.slot_granted, "Root must grant the exclusive Java slot")
    output = args.output.resolve()
    require(not output.exists(), "Refusing to reuse an existing attempt directory")
    classpath = args.classpath.resolve(strict=True)
    launcher = PHASE / "run_java.py"
    sources = {str(path): sha(path) for path in (Path(__file__).resolve(), launcher)}
    command = [sys.executable, str(launcher), "--output", str(output), "--classpath", str(classpath),
               "--main", MAIN, "--heap-mib", "128", "--slot-granted", "--",
               args.arm, str(args.characters), args.consumer, str(output / "store" / "values")]
    completed = subprocess.run(command, cwd=ROOT, check=False)
    try:
        require(completed.returncode == 0, "Supervised launcher failed; attempt is preserved and will not be retried")
        require(all(sha(Path(path)) == expected for path, expected in sources.items()), "Runner input changed")
        receipt = validate(output, args.arm, args.characters, args.consumer)
        receipt["runner_sources"] = sources
        save(output / "validation.json", receipt)
    except Exception as failure:
        if output.is_dir() and not (output / "validation.json").exists():
            save(output / "validation.json", {"status": "fail", "reason": str(failure), "runner_sources": sources})
        raise
    print(json.dumps({key: receipt[key] for key in (
        "status", "arm", "characters", "consumer", "requests", "source_calls",
        "cold_to_initialized_observations", "collected_misses", "natural_gc_count_delta",
    )}, sort_keys=True), flush=True)


if __name__ == "__main__":
    main()
